class CartController {

    // KHONG nhan userId tu client (khong co trong path/body) - Cart luon gan
    // voi nguoi dung dang xac thuc. Giong co che da thiet lap o Day 24/33: o
    // moi request da xac thuc bang Bearer JWT, principal la mot doi tuong Jwt
    // (KHONG phai UserDetails), id nguoi dung la claim sub da nhung vao JWT
    // luc phat hanh o Day 33 - doc qua
    // ((Jwt) authentication.getPrincipal()).getSubject(). TUYET DOI khong lay
    // userId tu mot truong do client tu gui (path/body), vi client co the gia
    // mao gia tri do de doc/sua gio hang cua nguoi khac.
    @org.springframework.web.bind.annotation.GetMapping("/api/cart/items")
    java.util.List<CartItemDto> getItems(org.springframework.security.core.Authentication authentication) {
        Long currentUserId = Long.valueOf(
            ((org.springframework.security.oauth2.jwt.Jwt) authentication.getPrincipal()).getSubject());
        Cart cart = cartService.findOrCreateForUser(currentUserId);
        return cart.getItems();
    }
}

