import org.springframework.cache.annotation.CacheEvict;
import org.springframework.cache.annotation.Cacheable;
import org.springframework.stereotype.Service;
import java.util.List;

@Service
class CategoryService {

    // Danh muc it thay doi -> cache theo key mac dinh (khong tham so).
    @Cacheable(value = "categories", unless = "#result.isEmpty()")
    public List<CategoryDto> findAll() {
        return loadAllFromDatabase();
    }

    // Xoa toan bo cache "categories" khi co category moi/bi sua/bi xoa.
    @CacheEvict(value = "categories", allEntries = true)
    public void invalidateCache() {
    }

    private List<CategoryDto> loadAllFromDatabase() { return List.of(); }
}
